declare namespace lib {
    interface Type<T> {
        check(value: unknown): value is T;
    }
    interface TraversalMethods {
        find<T>(type: Type<T>): Collection<T>;
    }
    interface MutationMethods<N> {
        remove(): Collection<N>;
    }
    interface Collection<N> extends TraversalMethods, MutationMethods<N> {
        filter(callback: (node: N) => boolean): Collection<N>;
        forEach(callback: (node: N, index: number) => void): this;
        nodes(): N[];
    }
    interface Core {
        (source: string): Collection<any>;
    }
    interface Declaration {
        declarations: (string | undefined)[];
    }
    interface NamedTypes {
        Declaration: Type<Declaration>;
    }
    type Api = Core & NamedTypes;
}
export = lib;
